using DayTrack.Models; using Microsoft.Data.Sqlite;
namespace DayTrack.Data;
public sealed class DayTrackDb
{
 readonly string _cs; readonly object _gate=new(); public string DataDirectory{get;} public string HistoryDirectory=>Path.Combine(DataDirectory,"History"); public string BackupDirectory=>Path.Combine(DataDirectory,"Backups");
 public DayTrackDb(){DataDirectory=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DayTrack");Directory.CreateDirectory(DataDirectory);Directory.CreateDirectory(HistoryDirectory);Directory.CreateDirectory(BackupDirectory);_cs=new SqliteConnectionStringBuilder{DataSource=Path.Combine(DataDirectory,"data.db"),Mode=SqliteOpenMode.ReadWriteCreate,Cache=SqliteCacheMode.Shared}.ToString();Init();}
 SqliteConnection Open(){var c=new SqliteConnection(_cs);c.Open();return c;}
 void Init(){lock(_gate){using var c=Open();using var q=c.CreateCommand();q.CommandText="""
 CREATE TABLE IF NOT EXISTS daily_stats(day TEXT PRIMARY KEY,active_seconds REAL NOT NULL DEFAULT 0,afk_seconds REAL NOT NULL DEFAULT 0,locked_seconds REAL NOT NULL DEFAULT 0,sleep_seconds REAL NOT NULL DEFAULT 0,paused_seconds REAL NOT NULL DEFAULT 0,pc_on_seconds REAL NOT NULL DEFAULT 0,key_presses INTEGER NOT NULL DEFAULT 0,mouse_clicks INTEGER NOT NULL DEFAULT 0,net_received INTEGER NOT NULL DEFAULT 0,net_sent INTEGER NOT NULL DEFAULT 0);
 CREATE TABLE IF NOT EXISTS app_daily(day TEXT NOT NULL,app_name TEXT NOT NULL,active_seconds REAL NOT NULL DEFAULT 0,launches INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(day,app_name));
 CREATE TABLE IF NOT EXISTS segments(id INTEGER PRIMARY KEY AUTOINCREMENT,start_utc TEXT NOT NULL,end_utc TEXT NOT NULL,state TEXT NOT NULL,app_name TEXT,process_name TEXT,window_title TEXT);
 """;q.ExecuteNonQuery();}}
 public void Add(DateTime day,double active,double afk,double locked,double sleep,double paused,double pc,long keys,long clicks,long rx,long tx,IReadOnlyDictionary<string,double> apps,IReadOnlyDictionary<string,long> launches){string d=day.ToString("yyyy-MM-dd");lock(_gate){using var c=Open();using var tr=c.BeginTransaction();using(var q=c.CreateCommand()){q.Transaction=tr;q.CommandText="""INSERT INTO daily_stats VALUES($d,$a,$f,$l,$s,$p,$pc,$k,$c,$rx,$tx) ON CONFLICT(day) DO UPDATE SET active_seconds=active_seconds+excluded.active_seconds,afk_seconds=afk_seconds+excluded.afk_seconds,locked_seconds=locked_seconds+excluded.locked_seconds,sleep_seconds=sleep_seconds+excluded.sleep_seconds,paused_seconds=paused_seconds+excluded.paused_seconds,pc_on_seconds=pc_on_seconds+excluded.pc_on_seconds,key_presses=key_presses+excluded.key_presses,mouse_clicks=mouse_clicks+excluded.mouse_clicks,net_received=net_received+excluded.net_received,net_sent=net_sent+excluded.net_sent;""";q.Parameters.AddWithValue("$d",d);q.Parameters.AddWithValue("$a",active);q.Parameters.AddWithValue("$f",afk);q.Parameters.AddWithValue("$l",locked);q.Parameters.AddWithValue("$s",sleep);q.Parameters.AddWithValue("$p",paused);q.Parameters.AddWithValue("$pc",pc);q.Parameters.AddWithValue("$k",keys);q.Parameters.AddWithValue("$c",clicks);q.Parameters.AddWithValue("$rx",rx);q.Parameters.AddWithValue("$tx",tx);q.ExecuteNonQuery();}
 foreach(var x in apps){using var q=c.CreateCommand();q.Transaction=tr;q.CommandText="INSERT INTO app_daily(day,app_name,active_seconds,launches) VALUES($d,$n,$s,0) ON CONFLICT(day,app_name) DO UPDATE SET active_seconds=active_seconds+excluded.active_seconds;";q.Parameters.AddWithValue("$d",d);q.Parameters.AddWithValue("$n",x.Key);q.Parameters.AddWithValue("$s",x.Value);q.ExecuteNonQuery();}
 foreach(var x in launches){using var q=c.CreateCommand();q.Transaction=tr;q.CommandText="INSERT INTO app_daily(day,app_name,active_seconds,launches) VALUES($d,$n,0,$v) ON CONFLICT(day,app_name) DO UPDATE SET launches=launches+excluded.launches;";q.Parameters.AddWithValue("$d",d);q.Parameters.AddWithValue("$n",x.Key);q.Parameters.AddWithValue("$v",x.Value);q.ExecuteNonQuery();}tr.Commit();}}
 public RangeSummary Summary(DateTime from,DateTime to){lock(_gate){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT COALESCE(SUM(active_seconds),0),COALESCE(SUM(afk_seconds),0),COALESCE(SUM(locked_seconds),0),COALESCE(SUM(sleep_seconds),0),COALESCE(SUM(paused_seconds),0),COALESCE(SUM(pc_on_seconds),0),COALESCE(SUM(key_presses),0),COALESCE(SUM(mouse_clicks),0),COALESCE(SUM(net_received),0),COALESCE(SUM(net_sent),0) FROM daily_stats WHERE day>=$f AND day<=$t";q.Parameters.AddWithValue("$f",from.ToString("yyyy-MM-dd"));q.Parameters.AddWithValue("$t",to.ToString("yyyy-MM-dd"));using var r=q.ExecuteReader();if(!r.Read())return new();return new(){ActiveSeconds=r.GetDouble(0),AfkSeconds=r.GetDouble(1),LockedSeconds=r.GetDouble(2),SleepSeconds=r.GetDouble(3),PausedSeconds=r.GetDouble(4),PcOnSeconds=r.GetDouble(5),KeyPresses=r.GetInt64(6),MouseClicks=r.GetInt64(7),NetworkReceived=r.GetInt64(8),NetworkSent=r.GetInt64(9)};}}
 public List<AppUsageRow> Apps(DateTime from,DateTime to,int limit=100){lock(_gate){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT app_name,SUM(active_seconds),SUM(launches) FROM app_daily WHERE day>=$f AND day<=$t GROUP BY app_name ORDER BY SUM(active_seconds) DESC LIMIT $m";q.Parameters.AddWithValue("$f",from.ToString("yyyy-MM-dd"));q.Parameters.AddWithValue("$t",to.ToString("yyyy-MM-dd"));q.Parameters.AddWithValue("$m",limit);using var r=q.ExecuteReader();var a=new List<AppUsageRow>();while(r.Read())a.Add(new(){AppName=r.GetString(0),ActiveSeconds=r.GetDouble(1),Launches=r.GetInt64(2)});return a;}}
 public void Backup(){lock(_gate){var src=Path.Combine(DataDirectory,"data.db");if(!File.Exists(src))return;var dst=Path.Combine(BackupDirectory,$"DayTrack_{DateTime.Now:yyyy-MM-dd_HH-mm-ss}.db");File.Copy(src,dst,true);foreach(var f in Directory.GetFiles(BackupDirectory,"DayTrack_*.db").OrderByDescending(File.GetCreationTimeUtc).Skip(8))try{File.Delete(f);}catch{}}}
}
